-- Shared music visibility, staff catalogue rights and immutable analysis history.
select no_plan();
select tests.create_shoppers_fixture();
reset role;
select tests.act_as('platform_staff');
select is((select count(*) from public.music_tracks),3::bigint,'platform_staff track visibility');
select is((select count(*) from public.music_analyses),3::bigint,'platform_staff analysis visibility');
select lives_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('jamendo','new','Staff track',1000,'fixture')$$,'catalogue staff can insert music');
select lives_ok($$update public.music_tracks set title = 'Updated draft' where provider_track_id = 'new'$$,'catalogue staff can update music');
select is((select title from public.music_tracks where provider_track_id = 'new'),'Updated draft','staff update applied');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'platform_staff cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'platform_staff cannot call backend analysis writer');
reset role;
select tests.act_as('organisation_owner');
select is((select count(*) from public.music_tracks),1::bigint,'organisation_owner track visibility');
select is((select count(*) from public.music_analyses),1::bigint,'organisation_owner analysis visibility');
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('upload','organisation_owner','Forbidden upload',1000,'fixture')$$,'42501',null,'organisation_owner cannot upload or insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'organisation_owner cannot update music');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'organisation_owner cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'organisation_owner cannot call backend analysis writer');
reset role;
select tests.act_as('organisation_manager');
select is((select count(*) from public.music_tracks),1::bigint,'organisation_manager track visibility');
select is((select count(*) from public.music_analyses),1::bigint,'organisation_manager analysis visibility');
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('upload','organisation_manager','Forbidden upload',1000,'fixture')$$,'42501',null,'organisation_manager cannot upload or insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'organisation_manager cannot update music');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'organisation_manager cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'organisation_manager cannot call backend analysis writer');
reset role;
select tests.act_as('other_organisation_member');
select is((select count(*) from public.music_tracks),1::bigint,'other_organisation_member track visibility');
select is((select count(*) from public.music_analyses),1::bigint,'other_organisation_member analysis visibility');
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('upload','other_organisation_member','Forbidden upload',1000,'fixture')$$,'42501',null,'other_organisation_member cannot upload or insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'other_organisation_member cannot update music');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'other_organisation_member cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'other_organisation_member cannot call backend analysis writer');
reset role;
select tests.act_as('anonymous_shopper');
select is((select count(*) from public.music_tracks),1::bigint,'anonymous_shopper track visibility');
select is((select count(*) from public.music_analyses),1::bigint,'anonymous_shopper analysis visibility');
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('upload','anonymous_shopper','Forbidden upload',1000,'fixture')$$,'42501',null,'anonymous_shopper cannot upload or insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'anonymous_shopper cannot update music');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'anonymous_shopper cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'anonymous_shopper cannot call backend analysis writer');
reset role;
select tests.act_as('signed_in_shopper');
select is((select count(*) from public.music_tracks),1::bigint,'signed_in_shopper track visibility');
select is((select count(*) from public.music_analyses),1::bigint,'signed_in_shopper analysis visibility');
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('upload','signed_in_shopper','Forbidden upload',1000,'fixture')$$,'42501',null,'signed_in_shopper cannot upload or insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'signed_in_shopper cannot update music');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'signed_in_shopper cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'signed_in_shopper cannot call backend analysis writer');
reset role;
select tests.act_as('supplier_member');
select is((select count(*) from public.music_tracks),1::bigint,'supplier_member track visibility');
select is((select count(*) from public.music_analyses),1::bigint,'supplier_member analysis visibility');
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('upload','supplier_member','Forbidden upload',1000,'fixture')$$,'42501',null,'supplier_member cannot upload or insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'supplier_member cannot update music');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','forged','{}',repeat('d',64))$$,'42501',null,'supplier_member cannot install analysis directly');
select ok(not has_function_privilege(current_user,'public.save_music_analysis(uuid,text,jsonb,text)','execute'),'supplier_member cannot call backend analysis writer');
reset role;
select tests.act_as_public();
select is((select count(*) from public.music_tracks),1::bigint,'public sees published tracks only');
select is((select count(*) from public.music_analyses),1::bigint,'public sees current published analysis only');
select throws_ok($$insert into public.music_tracks(provider,title,duration_ms,licence_code) values ('upload','Forbidden',1000,'fixture')$$,'42501',null,'public cannot upload music');
reset role;
update public.staff_roles set role = 'reviewer' where profile_id = tests.get_supabase_uid('platform_staff');
select tests.act_as('platform_staff');
select is((select count(*) from public.music_tracks),4::bigint,'non-editor staff can inspect drafts');
select throws_ok($$insert into public.music_tracks(provider,title,duration_ms,licence_code) values ('owned','Forbidden',1000,'fixture')$$,'42501',null,'reviewer cannot insert music');
with changed as (update public.music_tracks set title = 'Forbidden' returning *) select is((select count(*) from changed),0::bigint,'reviewer cannot update music');
reset role;
set local role service_role;
select throws_ok($$insert into public.music_tracks(provider,provider_track_id,title,duration_ms,licence_code) values ('jamendo','fixture-1','Duplicate',1000,'fixture')$$,'23505',null,'provider track identity unique for all shoppers');
select throws_ok($$insert into public.music_tracks(provider,title,duration_ms,licence_code) values ('jamendo','Missing identity',1000,'fixture')$$,'23514',null,'Jamendo needs provider identity');
select throws_ok($$update public.music_tracks set commercial_use = true$$,'23514',null,'commercial use cannot be enabled by backend');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256) values ('a3000000-0000-0000-0000-000000000001','another','{}',repeat('d',64))$$,'23505',null,'only one current analysis per track');
select throws_ok($$update public.music_analyses set analysis = '{"tempo_bpm":120}' where id = 'a4000000-0000-0000-0000-000000000001'$$,'23514',null,'analysis features immutable for backend');
select throws_ok($$update public.music_analyses set audio_sha256 = repeat('d',64) where id = 'a4000000-0000-0000-0000-000000000001'$$,'23514',null,'audio hash immutable');
select is(public.save_music_analysis('a3000000-0000-0000-0000-000000000001','fixture','{}',repeat('a',64)),'a4000000-0000-0000-0000-000000000001'::uuid,'identical analysis reused');
select lives_ok($$select public.save_music_analysis('a3000000-0000-0000-0000-000000000001','new','{"tempo_bpm":120}',repeat('d',64))$$,'reanalysis installs new current features');
select is((select count(*) from public.music_analyses where track_id = 'a3000000-0000-0000-0000-000000000001' and is_current),1::bigint,'reanalysis keeps exactly one current');
select is((select analysis from public.music_analyses where id = 'a4000000-0000-0000-0000-000000000001'),'{}'::jsonb,'historical payload preserved');
select lives_ok($$select public.save_music_analysis('a3000000-0000-0000-0000-000000000001','new','{"tempo_bpm":120}',repeat('d',64))$$,'repeat analysis reused');
select is((select count(*) from public.music_analyses where track_id = 'a3000000-0000-0000-0000-000000000001'),3::bigint,'repeat did not duplicate analysis');
select throws_ok($$select public.save_music_analysis('a3000000-0000-0000-0000-000000000001','invalid','[]',repeat('e',64))$$,'23514',null,'invalid reanalysis rolls back');
select is((select count(*) from public.music_analyses where track_id = 'a3000000-0000-0000-0000-000000000001' and is_current),1::bigint,'failed reanalysis retains current result');
reset role;
update public.shows set soundtrack_track_id = 'a3000000-0000-0000-0000-000000000001' where id = '93000000-0000-0000-0000-000000000003';
select tests.act_as('signed_in_shopper');
select lives_ok($$select public.save_show('93000000-0000-0000-0000-000000000003',tests.show_cues(),6000,'a4000000-0000-0000-0000-000000000001',0,'a0000000-0000-0000-0000-000000000001')$$,'show pins historical analysis and own planning session');
select is((select count(*) from public.music_analyses where id = 'a4000000-0000-0000-0000-000000000001'),1::bigint,'owner can still read pinned old analysis');
select throws_ok($$select public.save_show('93000000-0000-0000-0000-000000000003',tests.show_cues(),6000,'a4000000-0000-0000-0000-000000000002')$$,'23514',null,'show cannot pin analysis of another track');
select throws_ok($$select public.save_show('93000000-0000-0000-0000-000000000003',tests.show_cues(),6000,null,0,'a0000000-0000-0000-0000-000000000002')$$,'23514',null,'show cannot attach another shopper session');
reset role;
select tests.act_as('anonymous_shopper');
select is((select count(*) from public.music_analyses where id = 'a4000000-0000-0000-0000-000000000001'),0::bigint,'other shopper cannot use private show to read old analysis');
reset role;
set local role service_role;
select throws_ok($$update public.shows set soundtrack_track_id = 'ffffffff-ffff-ffff-ffff-ffffffffffff' where id = '93000000-0000-0000-0000-000000000003'$$,'23503',null,'show soundtrack foreign key enforced');
select throws_ok($$delete from public.music_analyses where id = 'a4000000-0000-0000-0000-000000000001'$$,'23503',null,'pinned analysis cannot be deleted');
select throws_ok($$delete from public.plan_sessions where id = 'a0000000-0000-0000-0000-000000000001'$$,'23503',null,'show planning provenance cannot be deleted');
select throws_ok($$update public.music_tracks set provider_track_id = 'reassigned' where id = 'a3000000-0000-0000-0000-000000000001'$$,'23514',null,'backend cannot reassign shared provider identity');
select throws_ok($$insert into public.music_analyses(track_id,algorithm,analysis,audio_sha256,is_current) values ('a3000000-0000-0000-0000-000000000001','bad','{}','bad',false)$$,'23514',null,'analysis fingerprint must be SHA-256 hex');
reset role;
update public.shows set soundtrack_track_id = 'a3000000-0000-0000-0000-000000000001' where id = '93000000-0000-0000-0000-000000000001';
select tests.act_as('organisation_owner');
select lives_ok($$select public.save_show('93000000-0000-0000-0000-000000000001',tests.show_cues(),6000,'a4000000-0000-0000-0000-000000000001')$$,'retailer show can pin historical analysis');
reset role;
select tests.act_as_public();
select is((select count(*) from public.music_analyses where id = 'a4000000-0000-0000-0000-000000000001'),1::bigint,'public can read historical analysis pinned by live retailer show');
reset role;
update public.music_tracks set status = 'withdrawn' where id = 'a3000000-0000-0000-0000-000000000001';
select tests.act_as_public();
select is((select count(*) from public.music_analyses),0::bigint,'withdrawn track hides current and historical analyses from public');
select finish();
